{{ $json.contexto }}

RESPUESTA PROPUESTA POR EL AGENTE (arquitectura {{ $json.arquitectura }}, intento {{ $json.intento }}):
{{ $json.respuesta }}

Calificá la respuesta propuesta segun la rubrica.

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "exactitud_factual": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5,
      "description": "Puntaje 1 a 5 segun la rubrica de exactitud factual contra el contexto de referencia"
    },
    "estado_veredicto": {
      "type": "string",
      "enum": ["ACEPTADO", "CORREGIR", "RECHAZADO"],
      "description": "Ruta de decision: ACEPTADO envia al cliente, CORREGIR reintenta, RECHAZADO escala a humano"
    },
    "categoria_error": {
      "type": "string",
      "enum": ["SIN_ERROR", "ALUCINACION", "OMISION_CRITICA", "DATO_INCOMPLETO", "FUERA_DE_ALCANCE", "FALTA_DE_CITA", "ESCALAMIENTO_OBLIGATORIO"],
      "description": "Categoria unica del error detectado"
    },
    "critica": {
      "type": "string",
      "description": "Maximo 2 frases indicandole al agente que cambiar concretamente"
    },
    "cita_verificada": {
      "type": "boolean",
      "description": "true si la respuesta cita una seccion del manual y la cita es correcta"
    }
  },
  "required": ["exactitud_factual", "estado_veredicto", "categoria_error", "critica", "cita_verificada"]
}

